window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a467323863e6e700"]={"versions": [{"id": "FIG-a467323863e6e700", "releases": ["R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Metamodell-Instanzdiagramm / Strukturelles Beziehungsdiagramm (UML-Objektdiagramm) der AUTOSAR Timing Extensions (<code>AUTOSAR_CP_TPS_TimingExtensions</code>).\n</li><li><strong>Architektur-Kontext:</strong> Formales Timing-Modell zur Spezifikation von Ausführungsreihenfolgen auf System- und Komponenten-Ebene. Es gehört zum Teilbereich der <em>Execution Order Constraints</em> (EOC) und definiert eine reguläre Ablaufsequenz (<code>executionOrderConstraintType == ordinaryEOC</code>) für ausführbare Software-Einheiten. Es dient Systemintegratoren und Timing-Tools als normative Vorgabe für RTE-Scheduling, Task-Layout und Schedulability-Analysen.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>ExecutionOrderConstraint</code> (EOC):</strong>\n<ul class=\"fig-list\"><li>Top-Level-Container des Timing-Constraints.\n</li><li>Spezifiziert über das Attribut <code>executionOrderConstraintType</code> die Art der Restriktion (hier: <code>ordinaryEOC</code>).\n</li></ul>\n</li><li><strong><code>EocExecutableEntityRef</code> (EOCEER):</strong>\n<ul class=\"fig-list\"><li>Über Komposition (ausgefüllte Raute) an das <code>EOC</code> gebundene Referenz-Knotenpunkte.\n</li><li>Kapselt die Einbindung einer konkreten Ausführungseinheit in den Ordnungsgraph.\n</li></ul>\n</li><li><strong><code>ExecutableEntity</code>:</strong>\n<ul class=\"fig-list\"><li>Zielentität im AUTOSAR-Modell (z. B. <code>RunnableEntity</code> einer SW-C oder <code>BswSchedulableEntity</code> / <code>BswCalledEntity</code> eines BSW-Moduls).\n</li><li>Jedes <code>EOCEER</code> referenziert über eine gerichtete Relation genau eine konkrete <code>ExecutableEntity</code>.\n</li></ul>\n</li><li><strong>Beziehungen &amp; Kardinalitäten:</strong>\n<ul class=\"fig-list\"><li><strong>Aggregation/Komposition:</strong> <code>EOC</code> → <code>EOCEER</code> [2..*] (im Schaubild konkret 4 Instanzen).\n</li><li><strong>Referenz:</strong> <code>EOCEER</code> → <code>ExecutableEntity</code> [1..1].\n</li><li><strong>Kanten-Relation <code>successor</code>:</strong> Gerichtete Assoziation zwischen aufeinanderfolgenden <code>EOCEER</code>-Elementen zur Konstruktion eines gerichteten Graphen (hier eine lineare Kette).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Graphensemantik:</strong> Die Kette $EOCEER_1 \\xrightarrow{\\text{successor}} EOCEER_2 \\xrightarrow{\\text{successor}} EOCEER_3 \\xrightarrow{\\text{successor}} EOCEER_4$ erzwingt eine strikte Halbordnung der Ausführungszeitpunkte (t_finish(EE_n) ≤ t_start(EE_n+1)).\n</li><li><strong>Semantik von <code>successor</code> vs. <code>directSuccessor</code>:</strong>\n<ul class=\"fig-list\"><li>Dargestellt ist <code>successor</code>: Erlaubt die Ausführung anderer, nicht im EOC genannter Entitäten oder Unterbrechungen (Präemptionen) zwischen EE_n und EE_n+1, solange die relative Reihenfolge gewahrt bleibt.\n</li><li>Im Gegensatz zu <code>directSuccessor</code> ist keine unmittelbare, unterbrechungsfreie Folge innerhalb desselben Kontexts gefordert.\n</li></ul>\n</li><li><strong>Synchronisationspfad:</strong> Die Kette gilt typischerweise bezogen auf denselben Aktivierungszyklus/dieselbe Periode oder über definierte Latenzzyklen hinweg (Pipeline-Verarbeitung).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>RTE- und OS-Konfiguration:</strong>\n<ul class=\"fig-list\"><li><strong>Task-Mapping:</strong> Die referenzierten Runnables müssen vom Integrator entweder sequentiell in denselben OS-Task gemappt oder über Task-Prioritäten, Task-Chaining (<code>ChainTask</code>) bzw. OS-Events so synchronisiert werden, dass die Reihenfolge unter allen Preemption-Szenarien unverletzlich ist.\n</li></ul>\n</li><li><strong>Datenkonsistenz ohne Locks:</strong>\n<ul class=\"fig-list\"><li>Durch Einhaltung des EOC können Produzent-Konsument-Pfade (z. B. Read-Before-Write über <code>InterRunnableVariable</code> oder PIMs) deterministisch realisiert werden, ohne blockierende OS-Ressourcen (<code>GetResource</code>/<code>ReleaseResource</code>) oder Spinlocks zu benötigen.\n</li></ul>\n</li><li><strong>Timing-Analyse &amp; Tracing (ARTI/AUTOSAR Runtime Interface):</strong>\n<ul class=\"fig-list\"><li>Timing-Verifikationstools (z. B. SymTA/S, INCHRON, TA Tool Suite) werten dieses XML-Fragment im ARXML direkt aus, um Verletzungen in Trace-Logs (MTA/OTM) statisch oder dynamisch als Timing-Fehler zu flaggen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-42ccc92b804c6eb1", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Metamodell-Instanzdiagramm / Strukturelles Beziehungsdiagramm (UML-Objektdiagramm) der AUTOSAR Timing Extensions (<code>AUTOSAR_CP_TPS_TimingExtensions</code>).\n</li><li><strong>Architektur-Kontext:</strong> Formales Timing-Modell zur Spezifikation von Ausführungsreihenfolgen auf System- und Komponenten-Ebene. Es gehört zum Teilbereich der <em>Execution Order Constraints</em> (EOC) und definiert eine reguläre Ablaufsequenz (<code>executionOrderConstraintType == ordinaryEOC</code>) für ausführbare Software-Einheiten. Es dient Systemintegratoren und Timing-Tools als normative Vorgabe für RTE-Scheduling, Task-Layout und Schedulability-Analysen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>eocX: ExecutionOrderConstraint</code>:</strong>\n<ul class=\"fig-list\"><li>Top-Level-Instanz des Timing-Constraints.\n</li><li>Enthält explizit die Attributbelegungen <code>executionOrderConstraintType = ordinaryEOC</code> und <code>isEvent = FALSE</code>.\n</li></ul>\n</li><li><strong><code>EOCExecutableEntityRef</code>-Instanzen:</strong>\n<ul class=\"fig-list\"><li>Vier konkrete Instanzknoten: <code>eoceerN</code>, <code>eoceerNplus1</code>, <code>eoceerNplus2</code> und <code>eoceerNplusM</code>.\n</li><li>Sind über die Kompositionsrolle <code>+orderedElements</code> (ausgefüllte Raute) an <code>eocX</code> gebunden.\n</li></ul>\n</li><li><strong><code>ExecutableEntity</code>-Instanzen:</strong>\n<ul class=\"fig-list\"><li>Vier Zielobjekte im Modell: <code>ee1: ExecutableEntity</code>, <code>ee2: ExecutableEntity</code>, <code>ee3: ExecutableEntity</code> und <code>ee4: ExecutableEntity</code>.\n</li><li>Werden von den jeweiligen <code>EOCExecutableEntityRef</code>-Knoten über die gerichtete Referenzrolle <code>executable</code> referenziert.\n</li></ul>\n</li><li><strong>Beziehungen:</strong>\n<ul class=\"fig-list\"><li><strong>Komposition:</strong> <code>eocX</code> → <code>+orderedElements</code> zu den Instanzen <code>eoceerN</code>, <code>eoceerNplus1</code>, <code>eoceerNplus2</code>, <code>eoceerNplusM</code>.\n</li><li><strong>Referenz:</strong> <code>eoceer*</code> $\\xrightarrow{\\text{executable}}$ <code>ee*</code>.\n</li><li><strong>Kanten-Relation <code>successor</code>:</strong> Gerichtete Assoziation zwischen den geordneten Referenzknoten (<code>eoceerN</code> → <code>eoceerNplus1</code> → <code>eoceerNplus2</code> → <code>eoceerNplusM</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Graphensemantik:</strong> Die Kette $EOCEER_1 \\xrightarrow{\\text{successor}} EOCEER_2 \\xrightarrow{\\text{successor}} EOCEER_3 \\xrightarrow{\\text{successor}} EOCEER_4$ erzwingt eine strikte Halbordnung der Ausführungszeitpunkte (t_finish(EE_n) ≤ t_start(EE_n+1)).\n</li><li><strong>Semantik von <code>successor</code> vs. <code>directSuccessor</code>:</strong>\n<ul class=\"fig-list\"><li>Dargestellt ist <code>successor</code>: Erlaubt die Ausführung anderer, nicht im EOC genannter Entitäten oder Unterbrechungen (Präemptionen) zwischen EE_n und EE_n+1, solange die relative Reihenfolge gewahrt bleibt.\n</li><li>Im Gegensatz zu <code>directSuccessor</code> ist keine unmittelbare, unterbrechungsfreie Folge innerhalb desselben Kontexts gefordert.\n</li></ul>\n</li><li><strong>Synchronisationspfad:</strong> Die Kette gilt typischerweise bezogen auf denselben Aktivierungszyklus/dieselbe Periode oder über definierte Latenzzyklen hinweg (Pipeline-Verarbeitung).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>RTE- und OS-Konfiguration:</strong>\n<ul class=\"fig-list\"><li><strong>Task-Mapping:</strong> Die referenzierten Runnables müssen vom Integrator entweder sequentiell in denselben OS-Task gemappt oder über Task-Prioritäten, Task-Chaining (<code>ChainTask</code>) bzw. OS-Events so synchronisiert werden, dass die Reihenfolge unter allen Preemption-Szenarien unverletzlich ist.\n</li></ul>\n</li><li><strong>Datenkonsistenz ohne Locks:</strong>\n<ul class=\"fig-list\"><li>Durch Einhaltung des EOC können Produzent-Konsument-Pfade (z. B. Read-Before-Write über <code>InterRunnableVariable</code> oder PIMs) deterministisch realisiert werden, ohne blockierende OS-Ressourcen (<code>GetResource</code>/<code>ReleaseResource</code>) oder Spinlocks zu benötigen.\n</li></ul>\n</li><li><strong>Timing-Analyse &amp; Tracing (ARTI/AUTOSAR Runtime Interface):</strong>\n<ul class=\"fig-list\"><li>Timing-Verifikationstools (z. B. SymTA/S, INCHRON, TA Tool Suite) werten dieses XML-Fragment im ARXML direkt aus, um Verletzungen in Trace-Logs (MTA/OTM) statisch oder dynamisch als Timing-Fehler zu flaggen.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-a467323863e6e700", "to": "FIG-42ccc92b804c6eb1", "fr": "R24-11", "tr": "R25-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>UML-Notation:</strong> Umstellung von schematischen Klassenblöcken mit Akronymen (<code>EOC</code>, <code>EOCEER</code>) auf formale UML-Objektinstanzen mit unterstrichenen Instanzbezeichnern (<code>eocX: ExecutionOrderConstraint</code>, <code>eoceerN</code>, <code>eoceerNplus1</code>, <code>eoceerNplus2</code>, <code>eoceerNplusM: EOCExecutableEntityRef</code>, <code>ee1</code> bis <code>ee4: ExecutableEntity</code>).\n</li><li><strong>Instanzattribute:</strong> Ergänzung der Attributwerte <code>executionOrderConstraintType = ordinaryEOC</code> und <code>isEvent = FALSE</code> im Objekt <code>eocX: ExecutionOrderConstraint</code>.\n</li><li><strong>Rollenbezeichnungen:</strong> Ergänzung der Rollenbezeichnung <code>+orderedElements</code> an der Kompositionsbeziehung sowie <code>executable</code> an den Referenzpfeilen zu den <code>ExecutableEntity</code>-Instanzen.\n</li><li><strong>Legende:</strong> Die separate textuelle Legendenbox (<code>Legend: EOC Execution Order Constraint, EER Executable Entity Reference</code>) entfällt durch die vollständige Ausformulierung der Klassennamen in den Objekten.\n</li></ul>"}]};
